function normalizePatrolNumbers(){let changed=false;(state.patrols||[]).forEach((patrol,index)=>{const next=patrolNumber(index+1);if(patrol.id!==next){patrol.id=next;changed=true}});return changed}
function nextPatrolNumber(){const max=(state.patrols||[]).reduce((highest,patrol)=>{const match=String(patrol.id||'').match(/(\d+)$/);return Math.max(highest,match?Number(match[1]):0)},0);return patrolNumber(max+1)}
