async function loadState(){try{const raw=await miniappsAI.storage.getItem(STORE_KEY);state=raw?JSON.parse(raw):seedState();if(!state.users||!state.sites)state=seedState();state.version=VERSION;const accountsChanged=ensureAdminAccount(state);const usersChanged=normalizeUserAccounts(state);const shiftsChanged=normalizeShiftState(state);const closed=processShiftClosures();if(normalizePatrolNumbers()||accountsChanged||usersChanged||shiftsChanged||closed)await saveState();}catch{state=seedState();normalizeUserAccounts(state);normalizePatrolNumbers();showToast(t('messages.error'))}}
const saveState=createStateSaver({storeKey:STORE_KEY,getState:()=>state,storage:miniappsAI.storage,onSaved:()=>{qualityStateSaved({t,getState:()=>state});x10RecordSaveSuccess()},onFailed:x10RecordSaveFailure,onConflict:()=>{x10RecordSaveConflict();showToast(t('x10.saveConflict'))},onError:()=>showToast(t('messages.error'))});
function showToast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function applyI18n(){document.documentElement.lang='ar';document.documentElement.dir='rtl';$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));}
function addAudit(action,actor=state.currentUser?.name||'النظام'){state.audit=Array.isArray(state.audit)?state.audit:[];state.audit.unshift({action,actor,time:`اليوم ${clock()}`});state.audit=state.audit.slice(0,50)}
function processShiftClosures(){const closed=closeExpiredAttendance(state,new Date());if(!closed.length)return false;state.notifications=Array.isArray(state.notifications)?state.notifications:[];closed.forEach(({user,at})=>{state.notifications.unshift({id:uid('n'),type:'autoCheckout',targetUserId:user.id,text:t('attendance.autoClosedAdmin',{name:user.name}),time:clock(at),read:false});addAudit('attendanceAutoOut',user.name);});state.notifications=state.notifications.slice(0,80);if(state.currentUser)closed.filter(item=>item.user.id===state.currentUser.id).forEach(()=>showToast(t('attendance.autoClosed')));return true}
function roleName(role){return t(`auth.${normalizeRole(role)}`)}
function init(){applyI18n();bindRegistration({getState:()=>state,t,normalizePhone,saveState,showToast});$('#versionLabel').textContent=VERSION;$('#footerVersion').textContent=VERSION;bindAuth();bindShell();initQualityLayer({t,getState:()=>state,getVersion:()=>VERSION});initX10Core({t,getState:()=>state,getVersion:()=>VERSION,saveState,showToast});initX20Core({t,getState:()=>state,getVersion:()=>VERSION,save:saveState});initX30Core({t,getState:()=>state,getVersion:()=>VERSION,save:saveState});initSessionGuard({t,getAccount:()=>currentAccount(),onWarning:()=>{$('#sessionLockWarning').hidden=false},onWarningClear:()=>{$('#sessionLockWarning').hidden=true},onExpire:()=>{state.currentUser=null;qualityWorkspaceExited();sessionWorkspaceExited();$('#workspace').hidden=true;$('#authScreen').hidden=false;showToast(t('session.expired'))}});$('#assistantMessages').innerHTML=`<div class="chat-bubble ai">${esc(t('assistant.welcome'))}</div>`;loadState().then(()=>{if(state.currentUser)enterWorkspace(state.currentUser)});}
function bindAuth(){$('#loginForm').addEventListener('submit',e=>{e.preventDefault();const phone=normalizePhone($('#loginPhone').value),pass=$('#loginPassword').value.trim();if(!phone||!pass){$('#loginError').textContent=t('auth.required');$('#loginError').hidden=false;return}const user=state.users.find(u=>normalizePhone(u.phone||u.username)===phone);if(!user||!user.password||user.password!==pass){$('#loginError').textContent=t('auth.invalidCredentials');$('#loginError').hidden=false;return}login(user)});$('#forgotPassword').addEventListener('click',()=>{const phone=normalizePhone($('#loginPhone').value);const message=phone?`${t('auth.resetSent')}\n${t('auth.phone')}: ${phone}`:t('auth.resetSent');const url=`https://api.whatsapp.com/send?phone=[CONTACT_REDACTED]&text=${encodeURIComponent(message)}`;try{const popup=window.open(url,'_blank','noopener,noreferrer');if(!popup)window.location.assign(url);}catch{window.location.assign(url)}showToast(t('auth.resetSent'));});$('#maintenanceLogin').addEventListener('click',()=>{$('#maintenanceScreen').hidden=true;});}
function login(user){state.currentUser={id:user.id,role:user.role,name:user.name};addAudit('login',user.name);if(user.autoCheckoutWarning){user.autoCheckoutWarning=false;showToast(t('attendance.nextTimeReminder'));}saveState();enterWorkspace(state.currentUser)}
function requestedPreviewView(){const value=String(window.location.hash||'').replace(/^#/,'').trim();return ['overview','map','attendance','patrols','dashcam','prep','reports','requests','people','archive','settings'].includes(value)?value:null}
