function bindShell(){$('#openSidebar').addEventListener('click',()=>$('#sidebar').classList.add('open'));$('#closeSidebar').addEventListener('click',()=>$('#sidebar').classList.remove('open'));const logout=()=>{clearInterval(shiftTimer);shiftTimer=null;state.currentUser=null;qualityWorkspaceExited();sessionWorkspaceExited();saveState();$('#workspace').hidden=true;$('#authScreen').hidden=false;showToast(t('messages.loggedOut'))};$('#logoutButton').addEventListener('click',logout);$('#topLogoutButton').addEventListener('click',logout);$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(!b.hidden){clearOpenedFromAdmin();renderView(b.dataset.view);$('#sidebar').classList.remove('open')}}));$('#roleSwitch').addEventListener('click',()=>showToast(t('messages.roleLocked')));$('#notificationButton').addEventListener('click',()=>$('#notificationsPanel').hidden=!$('#notificationsPanel').hidden);$('#closeNotifications').addEventListener('click',()=>$('#notificationsPanel').hidden=true);$('#markNotifications').addEventListener('click',()=>{state.notifications.filter(n=>isAdminRole(actor(state).role)||n.targetUserId===state.currentUser?.id||actor(state).role==='supervisor'&&!n.targetUserId).forEach(n=>n.read=true);saveState();renderNotifications();showToast(t('notifications.read'))});$('#assistantToggle').addEventListener('click',()=>$('#assistantPanel').hidden=!$('#assistantPanel').hidden);$('#closeAssistant').addEventListener('click',()=>$('#assistantPanel').hidden=true);bindAssistant({t,esc,modelId:AI_MODEL_ID});$('#contactButton').addEventListener('click',()=>showToast(t('common.contactHint')));$('#footerBackupLink').addEventListener('click',e=>{e.preventDefault();renderView('archive')})}
function renderView(view){const account=currentAccount(),role=normalizeRole(account.role||state.currentUser?.role||'guard');if(account.role!==role)account.role=role;if(state.currentUser&&state.currentUser.role!==role)state.currentUser.role=role;if(!canAccessView(role,view)){showToast(t('messages.noPermission'));const fallback=defaultViewForRole(role);if(view!==fallback)return renderView(fallback);return}if(activeView==='patrols'&&view!=='patrols')stopMobileCamera();if(activeView==='dashcam'&&view!=='dashcam')stopDashcam();activeView=view;$$('.view').forEach(v=>v.hidden=v.id!==`view-${view}`);$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#topbarViewTitle').textContent=t(`nav.${view}`);const fn={overview:renderOverview,map:renderMap,attendance:renderAttendance,patrols:renderPatrols,dashcam:renderDashcam,prep:renderPrep,reports:renderReports,requests:renderRequests,people:renderPeople,archive:renderArchive,settings:renderSettings}[view];if(fn)fn();renderNotifications();renderAdminReturn({activeView,t,renderView})}
function header(kicker,title,subtitle,action=''){return `<div class="view-header"><div><div class="kicker">${esc(t(kicker))}</div><h1>${esc(t(title))}</h1><p>${esc(t(subtitle))}</p></div>${action?`<div class="header-actions">${action}</div>`:''}</div>`}
function renderLeaderboards(){const eligible=state.users.filter(x=>x.role==='guard'||x.role==='supervisor'),rounds=[...eligible].sort((a,b)=>(b.patrols||0)-(a.patrols||0)||(b.score||0)-(a.score||0)).slice(0,3),weights={normal:1,important:2,high:3,critical:5},vulnerabilityScore=u=>state.reports.filter(r=>r.type==='vulnerability'&&r.by===u.name).reduce((sum,r)=>sum+(weights[r.severity]||1),0),vulnerabilities=[...eligible].map(u=>({...u,vulnerabilityScore:vulnerabilityScore(u)})).sort((a,b)=>b.vulnerabilityScore-a.vulnerabilityScore||(b.score||0)-(a.score||0)).slice(0,3),rows=(list,kind)=>list.map((x,i)=>`<div class="compact-rank-row"><span class="compact-rank ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span><span class="compact-avatar">${esc(initials(x.name))}</span><span class="compact-rank-name">${esc(x.name)}</span><strong>${kind==='rounds'?x.patrols||0:x.vulnerabilityScore||0}</strong><small>${t(kind==='rounds'?'patrol.rounds':'patrol.discoveries')} · ${t('patrol.pointsShort')}</small></div>`).join('');return `<section class="leaderboards-top" aria-label="${esc(t('patrol.leaderboard'))}"><article class="compact-leaderboard rounds-board"><div class="compact-board-head"><div><span class="compact-board-kicker">✦ ${t('patrol.rounds')}</span><h3>${t('patrol.roundLeaderboard')}</h3></div><span class="compact-board-mark">01</span></div><div class="compact-rank-list">${rows(rounds,'rounds')}</div></article><article class="compact-leaderboard vulnerability-board"><div class="compact-board-head"><div><span class="compact-board-kicker">⌖ ${t('patrol.vulnerabilities')}</span><h3>${t('patrol.vulnerabilityLeaderboard')}</h3></div><span class="compact-board-mark">01</span></div><div class="compact-rank-list">${rows(vulnerabilities,'vulnerabilities')}</div></article></section>`}
function renderOverview(){const u=state.currentUser||{}, present=state.users.filter(x=>x.role==='guard'&&x.status==='present').length, completed=state.patrols.filter(x=>x.status==='completed').length;$('#view-overview').innerHTML=header('brand.eyebrow','dashboard.title','dashboard.subtitle',`<button class="btn btn-secondary" data-go="map">⌖ ${t('dashboard.viewMap')}</button>`)+`<div class="notice-box ${u.role==='guard'?'good':''}">${esc(t('dashboard.welcome',{name:u.name||''}))} · ${esc(t(u.role==='guard'?'dashboard.todayProgress':'common.today'))}</div>${renderLeaderboards()}<div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>${t('dashboard.people')}</span><span class="stat-icon">♙</span></div><div class="stat-value">${present + (u.role==='guard'?1:0)}</div><div class="stat-foot good">${t('common.active')}</div></div><div class="stat-card"><div class="stat-top"><span>${t('dashboard.patrols')}</span><span class="stat-icon">✦</span></div><div class="stat-value">${completed}</div><div class="stat-foot">${t('patrol.score')}</div></div><div class="stat-card"><div class="stat-top"><span>${t('dashboard.coverage')}</span><span class="stat-icon">⌖</span></div><div class="stat-value">86%</div><div class="stat-foot good">+6% ${t('common.today')}</div></div><div class="stat-card"><div class="stat-top"><span>${t('dashboard.openReports')}</span><span class="stat-icon">!</span></div><div class="stat-value">${state.reports.filter(r=>r.status!=='closed').length}</div><div class="stat-foot">${t('dashboard.alerts')}</div></div></div><div class="dashboard-grid"><div class="card map-card"><div class="card-head"><h3>${t('map.title')}</h3><a href="#" data-go="map">${t('common.open')} ←</a></div><div class="map-panel"><div id="overviewMap" class="live-map"></div><div class="map-legend"><div class="legend-row"><i class="legend-dot"></i>${t('map.livePeople')}</div><div class="legend-row"><i class="legend-dot orange"></i>${t('map.geofences')}</div></div></div><div class="map-bottom"><span>● ${t('common.online')}</span><span>${t('map.lastUpdate')}: ${clock()}</span></div></div><div class="card"><div class="card-head"><h3>${t('dashboard.alerts')}</h3><a href="#" data-go="reports">${t('common.open')} ←</a></div><div class="alert-list">${state.notifications.slice(0,4).map(n=>`<div class="alert-item"><span class="alert-icon">!</span><div><p>${esc(n.text)}</p><small>${esc(n.time)}</small></div></div>`).join('')}</div><div class="card-head" style="margin-top:18px"><h3>${t('dashboard.recent')}</h3></div><div class="activity-list">${state.audit.slice(0,3).map(a=>`<div class="activity"><i class="activity-dot"></i><div><p>${esc(t(`audit.${a.action}`))} · ${esc(a.actor)}</p><small>${esc(a.time)}</small></div></div>`).join('')}</div></div></div>`;bindGo();setTimeout(()=>initMap('overviewMap'),50)}
