function getSite(){const u=state.users.find(x=>x.id===state.currentUser?.id)||state.users[0]||{};return state.sites.find(s=>s.name===u.site)||state.sites[0]||{name:t('common.unassigned'),lat:CENTER.lat,lng:CENTER.lng,radius:0,boundary:[]}}
function distanceMeters(a,b){const R=6371e3,p=Math.PI/180,dLat=(b.lat-a.lat)*p,dLon=(b.lng-a.lng)*p;const x=Math.sin(dLat/2)**2+Math.cos(a.lat*p)*Math.cos(b.lat*p)*Math.sin(dLon/2)**2;return Math.round(R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x)))}
function currentPosition(){const u=state.users.find(x=>x.id===state.currentUser?.id);const fresh=u?.locationAt&&Date.now()-u.locationAt<120000;return fresh&&Number.isFinite(Number(u.lat))&&Number.isFinite(Number(u.lng))?{lat:Number(u.lat),lng:Number(u.lng)}:null}
function geoCheck(){const site=getSite(),pos=currentPosition();return {inside:!!pos&&distanceMeters(pos,{lat:site.lat,lng:site.lng})<=site.radius,distance:pos?distanceMeters(pos,{lat:site.lat,lng:site.lng}):null,site}}
