function renderPatrols(){stopMobileCamera();const users=Array.isArray(state.users)?state.users:[],u=users.find(x=>x.id===state.currentUser?.id)||state.currentUser||users[0]||{};$('#view-patrols').innerHTML=header('nav.patrols','patrol.title','patrol.subtitle',`<button class="btn btn-primary" id="newPatrol">✦ ${t('patrol.new')}</button>`)+`<div class="camera-layout"><div class="camera-card"><div class="card-head"><div><h3>${t('patrol.directCamera')}</h3><small class="camera-quality-label">${t('patrol.highResolution')}</small></div><span class="pill warn">${capturedPhotos.length}/4</span></div><div class="camera-preview live-camera-preview"><video id="patrolVideo" autoplay playsinline muted></video><div class="camera-overlay"><strong id="cameraResolution">${t('patrol.cameraReady')}</strong><span>${t('patrol.cameraHint')}</span></div></div><div class="camera-controls direct-camera-controls"><div class="zoom-control"><label for="zoomControl">${t('patrol.zoom')}</label><input id="zoomControl" type="range" min="1" max="2" step="0.1" value="1" disabled><small>${t('patrol.zoomHint')}</small></div><button class="btn btn-outline focus-camera" id="focusCamera" type="button" disabled>${t('patrol.focusNow')}</button></div><div class="capture-actions"><button class="btn btn-primary" id="captureLivePhoto" type="button">${t('patrol.capture')}</button><label class="btn btn-secondary native-capture" for="nativePhoto">${t('patrol.useNativeFallback')}</label><input id="nativePhoto" type="file" accept="image/*" capture="environment" hidden></div><div class="camera-controls"><span class="pill dark">${t('patrol.requiredPhotos')}: ${capturedPhotos.length}/4</span><span class="camera-mobile-hint">${t('patrol.mobileCameraHint')}</span></div><div class="photo-strip" id="photoStrip">${capturedPhotos.map((p,i)=>`<div class="photo-thumb"><img src="${esc(p)}" alt=""><span>${i+1}</span></div>`).join('')}</div></div><div><div class="score-card"><div class="card-head"><h3>${t('patrol.leaderboard')}</h3><span>✦</span></div>${state.users.filter(x=>x.role==='guard'||x.role==='supervisor').sort((a,b)=>b.score-a.score).slice(0,3).map((x,i)=>`<div class="leader-row"><span class="leader-rank">${i+1}</span><span>${esc(x.name)}</span><small>${x.patrols} ${t('patrol.points')}</small><b class="score-badge">${x.score}</b></div>`).join('')}</div><div class="card" style="margin-top:15px"><div class="card-head"><h3>${t('patrol.report')}</h3><span class="pill">${esc(u.site)}</span></div><div class="field"><textarea id="patrolReport" rows="5" data-i18n-placeholder="patrol.reportPlaceholder" placeholder="${t('patrol.reportPlaceholder')}"></textarea></div><div class="notice-box">${t('patrol.watermark')}</div><button class="btn btn-primary btn-wide" id="finishPatrol">${t('patrol.finish')}</button><p class="form-error" id="patrolError" hidden></p></div></div></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>${t('patrol.history')}</h3><span class="pill good">${t('common.today')}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('patrol.number')}</th><th>${t('people.person')}</th><th>${t('common.location')}</th><th>${t('patrol.photos')}</th><th>${t('common.status')}</th></tr></thead><tbody>${state.patrols.map(p=>`<tr><td><b>${esc(p.id)}</b></td><td>${esc(p.guard)}</td><td>${esc(p.site)}</td><td>${Array.isArray(p.photos)?p.photos.length:Number(p.photoCount||p.photos)||0}/4</td><td><span class="pill ${p.status==='completed'?'good':'warn'}">${p.status==='completed'?t('common.approved'):t('common.sent')}</span></td></tr>`).join('')}</tbody></table></div></div>`;$('#nativePhoto').addEventListener('change',addNativePhotos);$('#captureLivePhoto').addEventListener('click',captureLivePhoto);$('#focusCamera').addEventListener('click',async()=>{const ok=await focusCamera();showToast(ok?t('patrol.focusNow'):t('patrol.cameraDenied'))});$('#zoomControl').addEventListener('input',event=>setCameraZoom(Number(event.target.value)));$('#finishPatrol').addEventListener('click',finishPatrol);$('#newPatrol').addEventListener('click',()=>{capturedPhotos=[];renderPatrols();showToast(t('patrol.cameraReady'))});if(capturedPhotos.length<4)openPatrolCamera()}
async function openPatrolCamera(){const video=$('#patrolVideo');if(!video)return;try{const info=await startMobileCamera(video);const resolution=$('#cameraResolution');if(resolution)resolution.textContent=t('patrol.cameraResolution',{width:info.width,height:info.height});const zoom=$('#zoomControl');if(zoom&&info.zoom){zoom.min=String(info.zoom.min);zoom.max=String(info.zoom.max);zoom.step=String(info.zoom.step);zoom.value=String(info.zoom.value);zoom.disabled=false}else if(zoom)zoom.disabled=true;const focus=$('#focusCamera');if(focus)focus.disabled=!info.focusSupported}catch{const resolution=$('#cameraResolution');if(resolution)resolution.textContent=t('patrol.cameraDenied');}}
async function addPatrolFiles(files){const room=4-capturedPhotos.length;if(room<=0){showToast(t('patrol.photosFull'));return}const meta={name:state.currentUser?.name||'',time:clock(),site:getSite()?.name||'',brand:t('brand.name')};let added=0;for(const file of files.slice(0,room)){try{capturedPhotos.push(await stampPhotoFile(file,meta));added++}catch{showToast(t('patrol.photoFailed'))}}if(added){stopMobileCamera();showToast(t('patrol.photoAdded',{count:added}));renderPatrols()}}
async function addNativePhotos(e){const input=e.target,files=Array.from(input.files||[]);input.value='';if(files.length)await addPatrolFiles(files)}
async function captureLivePhoto(){const button=$('#captureLivePhoto'),video=$('#patrolVideo');if(!video||capturedPhotos.length>=4){showToast(t('patrol.photosFull'));return}if(button)button.disabled=true;try{const file=await captureCameraFile(video);await addPatrolFiles([file])}catch{showToast(t('patrol.photoFailed'))}finally{if(button)button.disabled=false}}
function finishPatrol(){const err=$('#patrolError'),report=$('#patrolReport').value.trim(),u=state.users.find(x=>x.id===state.currentUser.id);if(u?.role==='guard'&&!geoCheck().inside){err.textContent=t('geo.checkOutBlocked');err.hidden=false;operationalNotification('outside',t('notifications.outside'));return}if(capturedPhotos.length!==4){err.textContent=t('patrol.missingPhotos');err.hidden=false;return}if(!report){err.textContent=t('patrol.missingReport');err.hidden=false;return}state.patrols.unshift({id:nextPatrolNumber(),guard:u.name,guardId:u.id,site:u.site,time:clock(),photos:capturedPhotos.slice(0,4),photoCount:capturedPhotos.length,status:'completed',report,points:4});u.patrols=(u.patrols||0)+1;u.score=(u.score||0)+4;addAudit('patrol');saveState();capturedPhotos=[];showToast(t('patrol.completed'));renderPatrols()}
function renderPrep(){const canEdit=isAdminRole(state.currentUser.role)||state.currentUser.role==='supervisor';$('#view-prep').innerHTML=header('nav.prep','prep.title','prep.subtitle',`<button class="btn btn-secondary" id="sendPrep">↗ ${t('prep.sendAdmin')}</button>`)+`<div class="dashboard-grid"><div class="card"><div class="card-head"><h3>${t('prep.people')}</h3><span class="pill warn">${t('prep.returned')}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('prep.people')}</th><th>${t('prep.site')}</th><th>${t('prep.shift')}</th><th>${t('prep.status')}</th></tr></thead><tbody>${state.users.filter(x=>x.role==='guard').map(x=>`<tr><td><div class="person-cell"><span class="mini-avatar">${initials(x.name)}</span>${esc(x.name)}</div></td><td>${esc(x.site)}</td><td>${t('dashboard.shiftMorning')}</td><td><span class="pill ${x.id==='u3'?'warn':'good'}">${x.id==='u3'?t('prep.returned'):t('prep.approved')}</span></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h3>${t('prep.patrols')}</h3><span class="pill good">${t('common.today')}</span></div>${state.patrols.map(p=>`<div class="setting-row"><div><strong>${esc(p.guard)}</strong><small>${esc(p.site)} · ${p.points} نقاط</small></div><span class="pill ${p.status==='completed'?'good':'warn'}">${p.status==='completed'?t('prep.approved'):t('prep.sent')}</span></div>`).join('')}<div class="notice-box" style="margin-top:15px">${t('prep.editHint')}</div></div></div>`;$('#sendPrep').addEventListener('click',()=>{showToast(t('prep.sent'));addAudit('settings');saveState()})}
function renderReports(){const typeOptions=['security','accident','fire','field','vulnerability'];const sevOptions=['normal','important','high','critical'];$('#view-reports').innerHTML=header('nav.reports','reports.title','reports.subtitle',`<button class="btn btn-primary" id="toggleReportForm">+ ${t('reports.new')}</button>`)+`<div class="card form-card" id="reportForm" hidden><h3>${t('reports.new')}</h3><div class="form-grid"><div class="field"><label>${t('reports.type')}</label><select id="reportType">${typeOptions.map(x=>`<option value="${x}">${t(`reports.${x}`)}</option>`).join('')}</select></div><div class="field"><label>${t('reports.severity')}</label><select id="reportSeverity">${sevOptions.map(x=>`<option value="${x}">${t(`reports.${x}`)}</option>`).join('')}</select></div><div class="field full"><label>${t('reports.description')}</label><textarea id="reportDescription" rows="4" placeholder="${t('reports.descriptionPlaceholder')}"></textarea></div></div><div class="header-actions"><button class="btn btn-primary" id="submitReport">${t('reports.submit')}</button><button class="btn btn-outline" id="cancelReport">${t('common.cancel')}</button></div></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>${t('nav.reports')}</h3><div class="tag-list"><span class="pill bad">${state.reports.filter(r=>r.status!=='closed').length} ${t('reports.open')}</span><span class="pill">${state.reports.length} ${t('common.items')}</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('reports.number')}</th><th>${t('reports.type')}</th><th>${t('reports.severity')}</th><th>${t('common.location')}</th><th>${t('common.status')}</th><th></th></tr></thead><tbody>${state.reports.map(r=>`<tr><td><b>${r.id}</b><small style="display:block;color:var(--muted)">${esc(r.title)}</small></td><td>${t(`reports.${r.type}`)}</td><td><span class="pill ${r.severity==='critical'||r.severity==='high'?'bad':r.severity==='important'?'warn':'good'}">${t(`reports.${r.severity}`)}</span></td><td>${esc(r.site)}</td><td>${t(`reports.${r.status}`)}</td><td>${r.status!=='closed'&&(isAdminRole(actor(state).role)||actor(state).role==='supervisor')?`<button class="btn btn-outline" data-close-report="${r.id}">${t('reports.closeReport')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;$('#toggleReportForm').addEventListener('click',()=>$('#reportForm').hidden=!$('#reportForm').hidden);$('#cancelReport').addEventListener('click',()=>$('#reportForm').hidden=true);$('#submitReport').addEventListener('click',submitReport);$$('[data-close-report]').forEach(b=>b.addEventListener('click',()=>{const r=state.reports.find(x=>x.id===b.dataset.closeReport);if(r){r.status='closed';addAudit('report');saveState();renderReports();showToast(t('reports.archive'))}}))}
function submitReport(){const type=$('#reportType').value,sev=$('#reportSeverity').value,desc=$('#reportDescription').value.trim();if(!desc){showToast(t('common.required'));return}const n=uid('BL');state.reports.unshift({id:n,type,severity:sev,title:desc.slice(0,34),site:getSite().name,status:sev==='critical'||sev==='high'?'inProgress':'open',time:`اليوم، ${clock()}`,by:state.currentUser.name});if(sev==='critical'||sev==='high')state.notifications.unshift({id:uid('n'),type:'high',text:t('notifications.high'),time:t('common.now'),read:false});addAudit('report');saveState();renderReports();showToast(t('reports.created',{number:n}))}
function renderRequests(){const current=actor(state),isGuard=current.role==='guard',isManager=isAdminRole(current.role)||current.role==='supervisor';state.warnings=Array.isArray(state.warnings)?state.warnings:[];state.notifications=Array.isArray(state.notifications)?state.notifications:[];const visibleRequests=visibleRequestsFor(state,current),visibleWarnings=visibleWarningsFor(state,current),guardOptions=warningRecipientsFor(state,current);$('#view-requests').innerHTML=header('nav.requests','requests.title','requests.subtitle',isGuard?`<button class="btn btn-primary" id="toggleRequestForm">+ ${t('requests.new')}</button>`:'')+`${isGuard?`<div class="card form-card" id="requestForm" hidden><h3>${t('requests.new')}</h3><div class="form-grid"><div class="field"><label>${t('requests.type')}</label><select id="requestType"><option value="leave">${t('requests.leave')}</option><option value="license">${t('requests.license')}</option><option value="equipment">${t('requests.equipment')}</option></select></div><div class="field full"><label>${t('requests.description')}</label><textarea id="requestDescription" rows="3"></textarea></div></div><button class="btn btn-primary" id="submitRequest">${t('requests.submit')}</button></div>`:''}<div class="card" style="margin-top:18px"><div class="item-list">${visibleRequests.length?visibleRequests.map(r=>`<div class="setting-row"><div><strong>${esc(r.title)}</strong><small>${esc(r.by)} · ${esc(r.time)}</small></div><span class="pill ${r.status==='approved'?'good':r.status==='rejected'?'bad':'warn'}">${t(`requests.${r.status}`)}</span>${isManager&&r.status==='pending'?`<div class="header-actions request-actions"><button class="btn btn-secondary" type="button" data-request-action="approved" data-request-id="${esc(r.id)}">${t('common.approve')}</button><button class="btn btn-danger" type="button" data-request-action="rejected" data-request-id="${esc(r.id)}">${t('common.reject')}</button></div>`:''}</div>`).join(''):`<div class="empty-state"><strong>${t('common.noData')}</strong>${t('requests.emptyHint')}</div>`}</div></div>${isManager?`<div class="card warning-manager-card"><div class="card-head"><div><h3>${t('warnings.issueTitle')}</h3><small>${t('warnings.issueHint')}</small></div><span class="pill warn">${visibleWarnings.filter(item=>item.status==='pending').length} ${t('warnings.pending')}</span></div><form id="warningForm" class="form-grid"><div class="field"><label for="warningGuard">${t('warnings.recipient')}</label><select id="warningGuard">${guardOptions.length?guardOptions.map(user=>`<option value="${esc(user.id)}">${esc(user.name)}</option>`).join(''):`<option value="">${t('warnings.noRecipients')}</option>`}</select></div><div class="field full"><label for="warningReason">${t('warnings.reason')}</label><textarea id="warningReason" rows="3" required></textarea></div><div class="header-actions full"><button class="btn btn-primary" type="submit" ${guardOptions.length?'':'disabled'}>${t('warnings.send')}</button></div></form></div>`:''}<div class="card warnings-card"><div class="card-head"><div><h3>${isGuard?t('warnings.myTitle'):t('warnings.sentTitle')}</h3><small>${t('warnings.subtitle')}</small></div><span class="pill dark">${visibleWarnings.length}</span></div><div class="item-list">${visibleWarnings.length?visibleWarnings.map(item=>{const signed=item.status==='signed';return `<div class="warning-row"><div><strong>${esc(item.reason)}</strong><small>${esc(item.guard)} · ${esc(item.sender)} · ${esc(item.createdAt||t('common.now'))}</small>${item.response?`<p>${esc(item.response)}</p>`:''}</div><span class="pill ${signed?'good':'warn'}">${signed?t('warnings.signed'):t('warnings.pending')}</span>${isGuard&&!signed?`<div class="warning-response"><textarea data-warning-response="${esc(item.id)}" rows="2" placeholder="${t('warnings.responsePlaceholder')}"></textarea><button class="btn btn-primary" data-sign-warning="${esc(item.id)}">${t('warnings.signAndReply')}</button></div>`:''}</div>`}).join(''):`<div class="empty-state">${t('warnings.empty')}</div>`}</div></div>`;if(isGuard){$('#toggleRequestForm')?.addEventListener('click',()=>$('#requestForm').hidden=!$('#requestForm').hidden);$('#submitRequest')?.addEventListener('click',()=>{const desc=$('#requestDescription').value.trim();if(!desc){showToast(t('common.required'));return}state.requests.unshift({id:uid('RQ'),type:$('#requestType').value,title:desc,by:current.name,byId:current.id,supervisorId:current.supervisorId||'',status:'pending',time:t('common.now')});addAudit('request');saveState();renderRequests();showToast(t('requests.created'))});$$('[data-sign-warning]').forEach(button=>button.addEventListener('click',()=>{const warning=state.warnings.find(item=>item.id===button.dataset.signWarning),response=$(`[data-warning-response="${button.dataset.signWarning}"]`)?.value.trim();if(!warning||!response){showToast(t('warnings.responseRequired'));return}warning.status='signed';warning.signedAt=new Date().toISOString();warning.response=response;warning.respondedBy=current.id;state.notifications.unshift({id:uid('n'),type:'warningResponse',targetUserId:warning.senderId,text:t('warnings.responseSent',{name:current.name}),time:t('common.now'),read:false});addAudit('warningSigned',current.name);saveState();renderRequests();showToast(t('warnings.signedSuccess'))}))}if(isManager){$$('[data-request-action]').forEach(button=>button.addEventListener('click',()=>{const request=state.requests.find(item=>item.id===button.dataset.requestId);if(!request)return;request.status=button.dataset.requestAction;request.decidedBy=current.id;request.decidedAt=t('common.now');state.notifications.unshift({id:uid('n'),type:'requestDecision',targetUserId:request.byId,text:`${t('requests.type')}: ${t(`requests.${request.status}`)}`,time:t('common.now'),read:false});addAudit('request',current.name);saveState();renderRequests();showToast(t(`requests.${request.status}`))}));$('#warningForm')?.addEventListener('submit',event=>{event.preventDefault();const guard=state.users.find(user=>user.id===$('#warningGuard').value),reason=$('#warningReason').value.trim();if(!guard||!reason){showToast(t('common.required'));return}const warning={id:uid('WN'),guardId:guard.id,guard:guard.name,senderId:current.id,sender:current.name,senderRole:current.role,supervisorId:current.role==='supervisor'?current.id:(guard.supervisorId||''),reason,status:'pending',createdAt:t('common.now'),signedAt:null,response:''};state.warnings.unshift(warning);state.notifications.unshift({id:uid('n'),type:'warning',targetUserId:guard.id,text:t('warnings.newNotice'),time:t('common.now'),read:false});addAudit('warningSent',current.name);saveState();renderRequests();showToast(t('warnings.sentSuccess'))})}}
function renderPeople(){renderPeopleView({state,t,esc,initials,roleName,saveState,showToast})}
function renderArchive(){const can=isAdminRole(state.currentUser.role),users=Array.isArray(state.users)?state.users:[],reports=Array.isArray(state.reports)?state.reports:[],patrols=Array.isArray(state.patrols)?state.patrols:[],openReports=reports.filter(r=>r.status!=='closed').length,completedPatrols=patrols.filter(p=>p.status==='completed').length;$('#view-archive').innerHTML=header('nav.archive','archive.title','archive.subtitle')+`<section class="archive-hero"><div><span class="archive-kicker">${t('archive.interfaceTitle')}</span><h2>${t('archive.runtimeTitle')}</h2><p>${t('archive.runtimeHint')}</p></div><div class="archive-hero-meta"><span class="archive-status-badge good">${t('common.online')}</span><strong>${t('common.version')} ${VERSION}</strong></div></section><div class="archive-stat-grid"><div class="archive-stat"><span>${t('dashboard.people')}</span><strong>${users.length}</strong><small>${t('archive.recordCount',{count:users.length})}</small></div><div class="archive-stat"><span>${t('dashboard.patrols')}</span><strong>${completedPatrols}</strong><small>${t('archive.patrolCount',{count:completedPatrols})}</small></div><div class="archive-stat"><span>${t('dashboard.openReports')}</span><strong>${openReports}</strong><small>${t('archive.reportCount',{count:openReports})}</small></div><div class="archive-stat"><span>${t('archive.daily')}</span><strong>${state.daily?.archived||0}</strong><small>${t('common.today')} · ${isoDate()}</small></div></div><div class="archive-layout"><div class="archive-primary-stack"><div class="card archive-control-card"><div class="card-head"><div><h3>${t('archive.daily')}</h3><small>${t('archive.subtitle')}</small></div><span class="pill">${isoDate()}</span></div><div class="notice-box">${t('archive.archiveHint')}</div><button class="btn btn-primary" id="archiveDay" ${can?'':'disabled'}>${t('archive.archiveNow')}</button></div><div class="card archive-control-card archive-export-card"><div class="card-head"><div><h3>${t('archive.backup')}</h3><small>${t('archive.backupHint')}</small></div><span class="archive-card-mark">ZIP</span></div><div class="archive-note"><strong>${t('archive.interfaceTitle')}</strong><span>${t('archive.interfaceHint')}</span></div>${backupToolsMarkup(t)}</div></div><div class="archive-secondary-stack"><div class="card archive-control-card"><div class="card-head"><div><h3>${t('archive.pdf')}</h3><small>${t('archive.pdfHint')}</small></div><span class="archive-card-mark">PDF</span></div><div class="file-drop"><span>${t('archive.chooseImages')}</span><input id="pdfImages" type="file" accept="image/*" multiple></div><button class="btn btn-secondary btn-wide" id="makePdf">${t('archive.makePdf')}</button></div><div class="card archive-control-card"><div class="card-head"><div><h3>${t('archive.maintenance')}</h3><small>${t('archive.maintenanceHint')}</small></div><label><input id="maintenanceToggle" class="toggle" type="checkbox" ${state.maintenance?'checked':''}></label></div><div class="archive-maintenance-state ${state.maintenance?'is-on':''}"><span></span><strong>${state.maintenance?t('common.maintenance'):t('common.online')}</strong><small>${state.maintenance?t('messages.maintenanceOn'):t('archive.maintenanceReady')}</small></div></div></div></div>`;$('#archiveDay').addEventListener('click',()=>{state.daily={date:isoDate(),shift:'morning',archived:(state.daily?.archived||0)+1};state.patrols=state.patrols.filter(p=>p.status!=='completed');addAudit('archive');saveState();showToast(t('archive.archived'));renderArchive()});bindBackupTools({state,t,saveState,showToast,renderArchive});$('#makePdf').addEventListener('click',makePdf);$('#maintenanceToggle').addEventListener('change',e=>{state.maintenance=e.target.checked;saveState();showToast(e.target.checked?t('messages.maintenanceOn'):t('messages.maintenanceOff'))})}
async function makePdf(){const files=[...($('#pdfImages').files||[])];if(!files.length){showToast(t('common.required'));return}if(!window.jspdf){showToast(t('messages.error'));return}const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'portrait',unit:'px',format:'a4'});for(let i=0;i<files.length;i++){const data=await fileData(files[i]);if(i)doc.addPage();doc.addImage(data,'JPEG',22,22,doc.internal.pageSize.getWidth()-44,doc.internal.pageSize.getHeight()-44)}doc.save(`مرفقات-${isoDate()}.pdf`);showToast(t('common.download'))}
function fileData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function renderSettings(){const today=new Date(),groups=shiftGroups(),rows=groups.map(group=>{const schedule=shiftForUser({shiftGroup:group.id},today,t,state);const count=state.users.filter(user=>user.shiftGroup===group.id).length;return `<div class="setting-row"><div><strong>${esc(t(group.nameKey))} · ${esc(t(group.shift==='morning'?'dashboard.shiftMorning':'dashboard.shiftEvening'))}</strong><small>${schedule.working?t('common.active'):t('common.archived')} · ${t('people.person')}: ${count}</small></div><span class="pill ${schedule.working?'good':'warn'}">${schedule.working?t('attendance.checkedIn'):t('attendance.restDay')}</span></div>`}).join('');$('#view-settings').innerHTML=header('nav.settings','settings.title','settings.subtitle')+`<div class="dashboard-grid"><div class="card form-card"><div class="field"><label>${t('settings.company')}</label><input id="companyName" value="شركة الحماية المتقدمة"></div><div class="field"><label>${t('settings.timezone')}</label><select><option>Asia/Riyadh · الرياض</option><option>Asia/Dubai · دبي</option></select></div><div class="setting-row"><div><strong>${t('settings.workingHours')}</strong><small>${t('settings.morning')} · ${t('settings.evening')}</small></div><span class="pill good">24 ${t('common.hours')}</span></div><div class="setting-row"><div><strong>${t('settings.release')}</strong><small>${t('common.version')}</small></div><b>${VERSION}</b></div><button class="btn btn-primary" id="saveSettings" style="margin-top:20px">${t('settings.save')}</button></div><div class="card"><div class="card-head"><div><h3>${t('attendance.currentShift')}</h3><small>${t('attendance.shiftCycle')}</small></div><span class="pill dark">${t('attendance.autoCheckout')}</span></div>${rows}<div class="notice-box" style="margin-top:14px">${t('attendance.autoClosedAdmin',{name:t('people.person')})}</div></div></div>`;$('#saveSettings').addEventListener('click',()=>{addAudit('settings');saveState();showToast(t('settings.saved'))})}
function renderNotifications(){const list=$('#notificationsList');if(!list)return;const current=actor(state),ns=(state.notifications||[]).filter(n=>isAdminRole(current.role)||n.targetUserId===current.id||current.role==='supervisor'&&!n.targetUserId);list.innerHTML=ns.length?ns.slice(0,6).map(n=>`<div class="notification-row"><b></b><div>${esc(n.text)}<small>${esc(n.time)}</small></div></div>`).join(''):`<div class="empty-state">${t('notifications.empty')}</div>`;$('#notificationDot').hidden=!ns.some(n=>!n.read)}
function startLocationWatch(){if(!navigator.geolocation)return;if(watchId)navigator.geolocation.clearWatch(watchId);watchId=navigator.geolocation.watchPosition(pos=>{const u=state.users.find(x=>x.id===state.currentUser?.id);if(!u)return;u.lat=pos.coords.latitude;u.lng=pos.coords.longitude;u.locationAt=Date.now();saveState()},()=>{}, {enableHighAccuracy:true,maximumAge:15000,timeout:10000})}

/* Operational controls: editable geofences, site access history and mobile alerts. */
let boundaryDraft=[],boundarySiteId=null,boundaryLayer=null,boundaryMap=null;
const personRoleLabel=u=>u?.name&&u.name.trim()?u.name:roleName(u?.role||'guard');
const pointInsidePolygon=(point,polygon)=>{let inside=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const xi=polygon[i][1],yi=polygon[i][0],xj=polygon[j][1],yj=polygon[j][0],hit=((yi>point.lat)!==(yj>point.lat))&&(point.lng<(xj-xi)*(point.lat-yi)/(yj-yi)+xi);if(hit)inside=!inside}return inside};
const sitePosition=(site,pos)=>{if(!pos||!site)return {inside:false,distance:null};const distance=distanceMeters(pos,{lat:site.lat,lng:site.lng});const inside=site.boundary?.length>=3?pointInsidePolygon(pos,site.boundary):distance<=Number(site.radius||0);return {inside,distance}};
function normalizeOperationalState(){
  if(!state)return;
  state.siteAccessLog=Array.isArray(state.siteAccessLog)?state.siteAccessLog:[];
  state.geoPresence=state.geoPresence&&typeof state.geoPresence==='object'?state.geoPresence:{};
  state.sites=(state.sites||[]).map(s=>({...s,boundary:Array.isArray(s.boundary)?s.boundary:[]}));
  if(state.currentUser){const u=state.users.find(x=>x.id===state.currentUser.id);if(u)state.currentUser.name=personRoleLabel(u);}
}
const originalLoadState=loadState;
loadState=async function(){await originalLoadState();normalizeOperationalState();await saveState();};
function mobileNotify(message){try{if('Notification' in window&&Notification.permission==='granted')new Notification('الفرسان الأولى',{body:String(message),tag:'alfursan-operation'});}catch{}}
function enableMobileAlerts(){try{if(!('Notification' in window)){showToast(t('settings.alertsUnsupported'));return;}Notification.requestPermission().then(permission=>{if(permission==='granted')showToast(t('settings.alertsEnabled'));else showToast(t('messages.mobileAlerts'));}).catch(()=>showToast(t('messages.mobileAlerts')));}catch{showToast(t('settings.alertsUnsupported'));}}
function appendSiteLog(event,u,site,pos,inside){if(!state||!u||!site)return;state.siteAccessLog.unshift({id:uid('SL'),date:isoDate(),time:clock(),event,user:personRoleLabel(u),role:u.role,site:site.name,lat:pos?.lat||null,lng:pos?.lng||null,distance:pos?distanceMeters(pos,{lat:site.lat,lng:site.lng}):null,inside});state.siteAccessLog=state.siteAccessLog.slice(0,300);addAudit(event==='entry'?'siteEntry':'siteExit',personRoleLabel(u));}
function operationalNotification(type,text){state.notifications=state.notifications||[];state.notifications.unshift({id:uid('n'),type,text,time:t('common.now'),read:false});state.notifications=state.notifications.slice(0,80);mobileNotify(text);}
const originalInitMap=initMap;
initMap=function(id='liveMap'){
  const m=originalInitMap(id);if(!m||!state)return m;
  state.sites.filter(s=>s.boundary?.length>=3).forEach(s=>L.polygon(s.boundary,{color:'#37b6bd',fillColor:'#37b6bd',fillOpacity:.12,weight:3}).addTo(m).bindTooltip(`${esc(t('map.boundarySite'))}: ${esc(s.name)}`));
  return m;
};
const originalGeoCheck=geoCheck;
geoCheck=function(){const site=getSite(),pos=currentPosition();if(site?.boundary?.length>=3){const result=sitePosition(site,pos);return {inside:result.inside,distance:result.distance,site};}return originalGeoCheck();};
function redrawBoundary(){if(!boundaryMap)return;if(boundaryLayer)boundaryMap.removeLayer(boundaryLayer);if(boundaryDraft.length>=2)boundaryLayer=L.polyline(boundaryDraft,{color:'#f5a24a',weight:3,dashArray:'6 5'}).addTo(boundaryMap);if(boundaryDraft.length>=3)boundaryLayer=L.polygon(boundaryDraft,{color:'#f5a24a',fillColor:'#f5a24a',fillOpacity:.16,weight:3}).addTo(boundaryMap);}
function bindBoundaryEditor(m){const select=$('#boundarySite'),start=$('#startBoundary'),clear=$('#clearBoundary'),save=$('#saveBoundary');if(!select||!m)return;boundaryMap=m;boundarySiteId=select.value||state.sites[0]?.id;const loadDraft=()=>{const site=state.sites.find(s=>s.id===boundarySiteId);boundaryDraft=site?.boundary?.map(p=>[Number(p[0]),Number(p[1])])||[];redrawBoundary();};select.addEventListener('change',()=>{boundarySiteId=select.value;loadDraft();});start.addEventListener('click',()=>{boundarySiteId=select.value;boundaryDraft=[];redrawBoundary();showToast(t('map.mapClick'));});clear.addEventListener('click',()=>{boundaryDraft=[];redrawBoundary();});save.addEventListener('click',()=>{if(boundaryDraft.length<3){showToast(t('map.boundaryNeedPoints'));return;}const site=state.sites.find(s=>s.id===boundarySiteId);if(!site)return;site.boundary=boundaryDraft.map(p=>[Number(p[0]),Number(p[1])]);const avg=site.boundary.reduce((a,p)=>({lat:a.lat+p[0],lng:a.lng+p[1]}),{lat:0,lng:0});site.lat=avg.lat/site.boundary.length;site.lng=avg.lng/site.boundary.length;site.radius=Math.max(...site.boundary.map(p=>distanceMeters({lat:site.lat,lng:site.lng},{lat:p[0],lng:p[1]})));saveState();showToast(t('map.boundarySaved'));renderView('map');});m.on('click',e=>{if(!$('#startBoundary')||$('#startBoundary').disabled)return;const active=$('#boundarySite')?.value;if(active!==boundarySiteId)return;boundaryDraft.push([e.latlng.lat,e.latlng.lng]);redrawBoundary();});loadDraft();}
const originalRenderMap=renderMap;
renderMap=function(){originalRenderMap();const view=$('#view-map');if(!view)return;if(!isAdminRole(state.currentUser?.role))return;const options=state.sites.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');view.insertAdjacentHTML('afterbegin',`<div class="card boundary-editor"><div class="card-head"><h3>${t('map.boundaryEditor')}</h3><span class="pill dark">${t('map.geofences')}</span></div><div class="form-grid"><div class="field"><label for="boundarySite">${t('map.boundarySelect')}</label><select id="boundarySite">${options}</select></div><div class="boundary-actions"><button class="btn btn-secondary" id="startBoundary">${t('map.startBoundary')}</button><button class="btn btn-outline" id="clearBoundary">${t('map.clearBoundary')}</button><button class="btn btn-primary" id="saveBoundary">${t('map.saveBoundary')}</button></div></div><p class="boundary-hint">${t('map.boundaryHint')}</p></div>`);setTimeout(()=>bindBoundaryEditor(map),100);};
const originalRenderAttendance=renderAttendance;
renderAttendance=function(){originalRenderAttendance();const view=$('#view-attendance');if(!view)return;const rows=(state.siteAccessLog||[]).filter(x=>x.date===isoDate()).slice(0,30);view.insertAdjacentHTML('beforeend',`<div class="card site-log-card"><div class="card-head"><h3>${t('attendance.siteLog')}</h3><span class="pill good">${rows.length}</span></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('common.time')}</th><th>${t('people.person')}</th><th>${t('attendance.siteLogEvent')}</th><th>${t('common.location')}</th><th>${t('attendance.distance')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td dir="ltr">${esc(r.time)}</td><td>${esc(r.user)}</td><td><span class="pill ${r.event==='entry'?'good':'warn'}">${t(r.event==='entry'?'attendance.siteEntry':'attendance.siteExit')}</span></td><td>${esc(r.site)}</td><td>${r.distance==null?'—':`${r.distance} م`}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${t('attendance.siteLogEmpty')}</div>`}</div>`);};
const originalRenderSettings=renderSettings;
renderSettings=function(){originalRenderSettings();const card=$('#view-settings .form-card');if(!card)return;card.insertAdjacentHTML('beforeend',`<div class="mobile-alert-card"><div class="card-head"><h3>${t('settings.mobileAlerts')}</h3><span class="pill">${t('settings.notifyHint')}</span></div><button class="btn btn-secondary" id="enableMobileAlerts">${t('settings.enableMobileAlerts')}</button></div>`);$('#enableMobileAlerts').addEventListener('click',enableMobileAlerts);};
const originalStartLocationWatch=startLocationWatch;
startLocationWatch=function(){if(!navigator.geolocation){showToast(t('messages.locationRequired'));return;}if(watchId)navigator.geolocation.clearWatch(watchId);watchId=navigator.geolocation.watchPosition(pos=>{const u=state.users.find(x=>x.id===state.currentUser?.id);if(!u)return;u.lat=pos.coords.latitude;u.lng=pos.coords.longitude;u.locationAt=Date.now();const site=getSite(),result=sitePosition(site,{lat:u.lat,lng:u.lng}),previous=state.geoPresence[u.id];state.geoPresence[u.id]=result.inside;if(previous!==undefined&&previous!==result.inside){appendSiteLog(result.inside?'entry':'exit',u,site,{lat:u.lat,lng:u.lng},result.inside);if(!result.inside){operationalNotification('outside',t('notifications.outside'));showToast(t('geo.violation'));}else{operationalNotification('inside',t('geo.transitionInside'));}}saveState()},()=>showToast(t('geo.permission')),{enableHighAccuracy:true,maximumAge:15000,timeout:10000});};
const originalAttendanceAction=attendanceAction;
attendanceAction=function(type){const u=state.users.find(x=>x.id===state.currentUser?.id),site=getSite(),beforeIn=u?.checkIn,beforeOut=u?.checkOut,check=geoCheck();originalAttendanceAction(type);const changed=type==='in'?!beforeIn&&!!u?.checkIn:!beforeOut&&!!u?.checkOut;if(changed){appendSiteLog(type==='in'?'entry':'exit',u,site,currentPosition(),check.inside);saveState();renderAttendance();}if(type==='out'&&!check.inside)mobileNotify(t('notifications.outside'));};
const originalSubmitReport=submitReport;
submitReport=function(){const before=state.reports?.length||0;originalSubmitReport();if((state.reports?.length||0)>before){const report=state.reports[0];if(['high','critical'].includes(report.severity))mobileNotify(t('notifications.high'));}};
function greenApiConfig(){const current=state.greenApi&&typeof state.greenApi==='object'?state.greenApi:{};state.greenApi={apiUrl:String(current.apiUrl||'https://api.green-api.com').replace(/\/+$/,''),instanceId:String(current.instanceId||''),apiToken:String(current.apiToken||''),groupChatId:String(current.groupChatId||''),groupName:String(current.groupName||'SAPAC'),autoSend:Boolean(current.autoSend)};return state.greenApi}
function normalizeGreenGroupId(value){const clean=String(value||'').trim();return clean?(clean.endsWith('@g.us')?clean:`${clean}@g.us`):''}
function greenApiFields(){return {apiUrl:String($('#greenApiUrl')?.value||'https://api.green-api.com').trim().replace(/\/+$/,''),instanceId:String($('#greenApiInstance')?.value||'').trim(),apiToken:String($('#greenApiToken')?.value||'').trim(),groupChatId:normalizeGreenGroupId($('#greenApiGroup')?.value),groupName:'SAPAC',autoSend:Boolean($('#greenApiAuto')?.checked)}}
function greenApiReady(config=greenApiConfig()){return Boolean(config.apiUrl&&config.instanceId&&config.apiToken&&config.groupChatId)}
function greenApiEndpoint(action,config=greenApiConfig()){return `${config.apiUrl}/waInstance${encodeURIComponent(config.instanceId)}/${action}/${encodeURIComponent(config.apiToken)}`}
async function sendGreenApiMessage(message,config=greenApiConfig()){if(!greenApiReady(config))throw new Error('GREEN_API_NOT_CONFIGURED');const response=await fetch(greenApiEndpoint('sendMessage',config),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chatId:normalizeGreenGroupId(config.groupChatId),message})});const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{}if(!response.ok)throw new Error(data.message||data.error||`HTTP_${response.status}`);return data}
function greenApiPatrolMessage(patrol){return [t('settings.greenApiMessageTitle'),`${t('settings.greenApiNumber')}: ${patrol.id}`,`${t('settings.greenApiGuard')}: ${patrol.guard}`,`${t('settings.greenApiSite')}: ${patrol.site}`,`${t('settings.greenApiTime')}: ${patrol.time}`,`${t('settings.greenApiPhotos')}: ${Array.isArray(patrol.photos)?patrol.photos.length:Number(patrol.photoCount||patrol.photos)||0}/4`,`${t('settings.greenApiReport')}: ${patrol.report}`].join('\n')}
async function sendPatrolToGreenApi(patrol,quiet=false){const config=greenApiConfig();if(!greenApiReady(config)){if(!quiet)showToast(t('settings.greenApiNotReady'));return false}try{const result=await sendGreenApiMessage(greenApiPatrolMessage(patrol),config);patrol.greenApiStatus='sent';patrol.greenApiSentAt=clock();patrol.greenApiMessageId=result?.idMessage||'';await saveState();if(!quiet)showToast(t('settings.greenApiSent'));return true}catch(error){patrol.greenApiStatus='failed';await saveState();if(!quiet)showToast(t('settings.greenApiFailed'));return false}}
function saveGreenApiFields(){const config=greenApiFields();if(!greenApiReady(config)){showToast(t('settings.greenApiRequired'));return false}state.greenApi=config;addAudit('settings');saveState();showToast(t('settings.greenApiSaved'));return true}
const originalRenderPatrolsForGreenApi=renderPatrols;
renderPatrols=function(){originalRenderPatrolsForGreenApi();const view=$('#view-patrols');if(!view)return;const latest=(state.patrols||[]).find(p=>p.status==='completed');const config=greenApiConfig();view.insertAdjacentHTML('beforeend',`<div class="card green-api-patrol-card"><div class="card-head"><div><h3>${t('settings.greenApiLast')}</h3><small>${t('settings.greenApiSubtitle')}</small></div><span class="pill ${greenApiReady(config)?'good':'warn'}">${greenApiReady(config)?t('settings.greenApiReady'):t('settings.greenApiNotReady')}</span></div><div class="green-api-patrol-row"><div><strong>${latest?esc(latest.id):t('common.noData')}</strong><small>${latest?`${esc(latest.site)} · ${esc(latest.time)}`:t('settings.greenApiPending')}</small></div><div class="header-actions"><span class="pill ${latest?.greenApiStatus==='sent'?'good':latest?.greenApiStatus==='failed'?'bad':'warn'}">${latest?.greenApiStatus==='sent'?t('settings.greenApiSent'):latest?.greenApiStatus==='failed'?t('settings.greenApiFailed'):t('settings.greenApiPending')}</span><button class="btn btn-secondary" id="sendLatestPatrol" ${latest?'':'disabled'}>${t('settings.greenApiManual')}</button></div></div></div>`);$('#sendLatestPatrol')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;await sendPatrolToGreenApi(latest);renderPatrols()})};
