const originalRenderSettingsForGreenApi=renderSettings;
renderSettings=function(){originalRenderSettingsForGreenApi();const card=$('#view-settings .form-card');if(!card)return;const config=greenApiConfig();card.insertAdjacentHTML('beforeend',`<div class="green-api-card"><div class="card-head"><div><h3>${t('settings.greenApiTitle')}</h3><small>${t('settings.greenApiSubtitle')}</small></div><span class="integration-mark">WA</span></div><div class="form-grid"><div class="field"><label for="greenApiUrl">${t('settings.greenApiUrl')}</label><input id="greenApiUrl" dir="ltr" value="${esc(config.apiUrl)}"></div><div class="field"><label for="greenApiInstance">${t('settings.greenApiInstance')}</label><input id="greenApiInstance" dir="ltr" value="${esc(config.instanceId)}" autocomplete="off"></div><div class="field"><label for="greenApiToken">${t('settings.greenApiToken')}</label><input id="greenApiToken" type="password" dir="ltr" value="${esc(config.apiToken)}" autocomplete="new-password"></div><div class="field"><label for="greenApiGroup">${t('settings.greenApiGroup')}</label><input id="greenApiGroup" dir="ltr" value="${esc(config.groupChatId)}" placeholder="120xxxxxxxx@g.us"></div></div><p class="boundary-hint">${t('settings.greenApiGroupHint')}</p><label class="check-row green-api-toggle"><input id="greenApiAuto" type="checkbox" ${config.autoSend?'checked':''}><span>${t('settings.greenApiAuto')}</span></label><div class="header-actions"><button class="btn btn-primary" id="saveGreenApi">${t('settings.greenApiSave')}</button><button class="btn btn-outline" id="testGreenApi">${t('settings.greenApiTest')}</button></div></div>`);$('#saveGreenApi').addEventListener('click',saveGreenApiFields);$('#testGreenApi').addEventListener('click',async()=>{const next=greenApiFields();if(!greenApiReady(next)){showToast(t('settings.greenApiRequired'));return}try{await sendGreenApiMessage(t('settings.greenApiTestMessage'),next);showToast(t('settings.greenApiTestSent'))}catch{showToast(t('settings.greenApiTestFailed'))}})};
/* Workspace access and multi-project controls. */
function workspaceSnapshot(keys){const snapshot={};keys.forEach(key=>{snapshot[key]=state[key];});return snapshot;}
function workspaceRestore(snapshot){Object.keys(snapshot).forEach(key=>{state[key]=snapshot[key];});}
function workspaceScopedData(){
  const users=scopedUsers(state),sites=visibleSites(state);
  return {users,sites,patrols:visibleRecords(state,'patrols','guard'),reports:visibleRecords(state,'reports','by'),requests:visibleRecords(state,'requests','by')};
}
function renderWithWorkspaceScope(renderFn,keys,delay=0){
  const snapshot=workspaceSnapshot(keys),data=workspaceScopedData();
  keys.forEach(key=>{if(data[key])state[key]=data[key];});
  try{renderFn();}finally{if(delay)setTimeout(()=>workspaceRestore(snapshot),delay);else workspaceRestore(snapshot);}
}
